export const runtimeStyle = ":root {\n  --vh-bg: #ffffff;\n  --vh-surface: #f7f7f8;\n  --vh-sunk: #f1f1f3;\n  --vh-line: #e4e4e7;\n  --vh-edge: #d4d4d8;\n  --vh-ink: #18181b;\n  --vh-muted: #52525b;\n  --vh-faint: #a1a1aa;\n  --vh-accent: #2563eb;\n  --vh-on-accent: #ffffff;\n  --vh-accent-soft: #dbeafe;\n  --vh-accent-ink: #1d4ed8;\n  --vh-ok: #15803d;\n  --vh-warn: #b45309;\n  --vh-bad: #b91c1c;\n  --vh-ok-soft: #dcfce7;\n  --vh-warn-soft: #fef3c7;\n  --vh-bad-soft: #fee2e2;\n  --vh-cursorline: rgba(37, 99, 235, 0.07);\n  --vh-visual: rgba(37, 99, 235, 0.22);\n  --vh-search: #ff3333;\n  --vh-on-search: #ffffff;\n  --vh-search-cur: #b00000;\n  --vh-search-outline: #ffd400;\n  --vh-mark: #b45309;\n  --vh-fold: #52525b;\n  --vh-fold-bg: #f1f1f3;\n  --vh-comment: rgba(245, 158, 11, 0.22);\n  --vh-comment-mark: #f59e0b;\n  --vh-gutter-fg: #a1a1aa;\n  --vh-gutter-cur: #18181b;\n  --vh-font-display: ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  --vh-font-body: ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n  --vh-font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \"Liberation Mono\", monospace;\n  --vh-radius: 6px;\n  --vh-shadow: 0 6px 24px rgba(24, 24, 27, 0.14);\n  --vh-display-weight: 650;\n  --vh-display-tracking: -0.01em;\n  --vh-display-transform: none;\n  --vh-measure: 72ch;\n  --vh-gutter-w: 3.5rem;\n}\n:root[data-vh-scheme=\"dark\"] {\n  --vh-bg: #1e1e2e;\n  --vh-surface: #313244;\n  --vh-sunk: #181825;\n  --vh-line: #313244;\n  --vh-edge: #45475a;\n  --vh-ink: #cdd6f4;\n  --vh-muted: #a6adc8;\n  --vh-faint: #6c7086;\n  --vh-accent: #89b4fa;\n  --vh-on-accent: #1e1e2e;\n  --vh-accent-soft: rgba(137, 180, 250, 0.16);\n  --vh-accent-ink: #89b4fa;\n  --vh-ok: #a6e3a1;\n  --vh-warn: #f9e2af;\n  --vh-bad: #f38ba8;\n  --vh-ok-soft: rgba(166, 227, 161, 0.14);\n  --vh-warn-soft: rgba(249, 226, 175, 0.14);\n  --vh-bad-soft: rgba(243, 139, 168, 0.14);\n  --vh-cursorline: rgba(205, 214, 244, 0.06);\n  --vh-visual: rgba(137, 180, 250, 0.28);\n  --vh-search: #ff3333;\n  --vh-on-search: #ffffff;\n  --vh-search-cur: #b00000;\n  --vh-search-outline: #ffd400;\n  --vh-mark: #f9e2af;\n  --vh-fold: #a6adc8;\n  --vh-fold-bg: #181825;\n  --vh-comment: rgba(249, 226, 175, 0.18);\n  --vh-comment-mark: #f9e2af;\n  --vh-gutter-fg: #6c7086;\n  --vh-gutter-cur: #b4befe;\n  --vh-shadow: 0 6px 24px rgba(0, 0, 0, 0.4);\n}\n/* ---- runtime/core.css ---- */\n/* core.css -- the base every runtime module's UI sits on (piece A). Tokens only.\n   All runtime UI lives inside #vh-ui (VH.ui.layer): a zero-size box at its\n   containing block's origin, so absolute children can be placed over the\n   document and fixed children over the viewport, all above the page. */\n\n#vh-ui {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 0;\n  height: 0;\n  z-index: 2147483000;\n  font: 13px/1.45 var(--vh-font-body, system-ui, sans-serif);\n  color: var(--vh-ink);\n  text-align: left;\n  letter-spacing: normal;\n  text-transform: none;\n  -webkit-font-smoothing: antialiased;\n}\n[data-vh-ui] *, [data-vh-ui] *::before, [data-vh-ui] *::after { box-sizing: border-box; }\n\n/* VH.toast */\n.vh-toast {\n  position: fixed;\n  right: 16px;\n  bottom: 40px;\n  max-width: min(420px, calc(100vw - 32px));\n  padding: 8px 12px;\n  border-radius: var(--vh-radius);\n  background: var(--vh-ink);\n  color: var(--vh-bg);\n  box-shadow: var(--vh-shadow);\n  opacity: 0;\n  transform: translateY(6px);\n  transition: opacity 0.15s, transform 0.15s;\n  pointer-events: none;\n}\n.vh-toast.vh-show { opacity: 1; transform: none; }\n.vh-toast.vh-toast-error { background: var(--vh-bad); color: var(--vh-bg); }\n\n/* VH.clip: the off-screen execCommand sink and the last-resort copy dialog */\n.vh-clip-sink { position: fixed; top: 0; left: 0; width: 1px; height: 1px; opacity: 0; pointer-events: none; }\n.vh-clipdlg {\n  position: fixed;\n  left: 50%;\n  top: 12vh;\n  transform: translateX(-50%);\n  width: min(640px, calc(100vw - 32px));\n  padding: 12px;\n  border: 1px solid var(--vh-edge);\n  border-radius: var(--vh-radius);\n  background: var(--vh-surface);\n  box-shadow: var(--vh-shadow);\n}\n.vh-clipdlg-head { display: flex; align-items: center; gap: 12px; margin-bottom: 8px; color: var(--vh-ink); }\n.vh-clipdlg-head span { flex: 1; }\n.vh-clipdlg-close {\n  padding: 3px 10px;\n  border: 1px solid var(--vh-edge);\n  border-radius: calc(var(--vh-radius) * 0.6);\n  background: var(--vh-bg);\n  color: var(--vh-ink);\n  font: inherit;\n  cursor: pointer;\n}\n.vh-clipdlg-text {\n  display: block;\n  width: 100%;\n  height: min(50vh, 360px);\n  padding: 8px;\n  border: 1px solid var(--vh-line);\n  border-radius: calc(var(--vh-radius) * 0.6);\n  background: var(--vh-bg);\n  color: var(--vh-ink);\n  font: 12px/1.5 var(--vh-font-mono, ui-monospace, monospace);\n  resize: none;\n}\n\n@media print { [data-vh-ui] { display: none !important; } }\n/* ---- runtime/lines.css ---- */\n/* lines.css -- the gutter, pre lines and folds (piece C1).\n *\n * Gutter: rows in VH.ui.layer, placed by lines.js beside the text column. Each\n * row holds its absolute number (.vh-n); in relative mode (.vh-rel on the\n * gutter) every row but the cursor's draws data-rel instead, so numbertoggle\n * flips with one class. Signs: data-mark on the left, a comment bar (.vh-ln-c)\n * on the right edge, next to the text, like gitsigns. .vh-nonu hides the\n * numbers and keeps the signs (<leader>ul, as in nvim).\n */\n\n.vh-gutter-probe { position: absolute; visibility: hidden; width: var(--vh-gutter-w, 3.5rem); height: 0; }\n\n/* Font metric probes (lines.js measureFonts) */\n.vh-metric {\n  position: absolute;\n  top: 0;\n  left: 0;\n  visibility: hidden;\n  white-space: nowrap;\n  line-height: normal;\n  letter-spacing: normal;\n}\n.vh-metric > span { display: inline-block; width: 0; height: 0; vertical-align: baseline; }\n\n\n\n/* Changes inside the gutter never relayout the document. */\n.vh-gutter { position: absolute; top: 0; left: 0; height: 0; contain: layout style; }\n\n.vh-ln {\n  position: absolute;\n  left: 0;\n  right: 0;\n  padding-right: 14px;\n  text-align: right;\n  white-space: nowrap;\n  font: 12px/16px var(--vh-font-mono, ui-monospace, monospace);\n  font-variant-numeric: tabular-nums;\n  letter-spacing: 0;\n  color: var(--vh-gutter-fg);\n  user-select: none;\n  -webkit-user-select: none;\n  pointer-events: none;\n}\n.vh-ln.vh-ln-x { display: none; }\n.vh-ln.vh-ln-cur { color: var(--vh-gutter-cur); font-weight: 700; }\n\n.vh-gutter.vh-rel .vh-ln:not(.vh-ln-cur) > .vh-n { display: none; }\n.vh-gutter.vh-rel .vh-ln:not(.vh-ln-cur)::after { content: attr(data-rel); }\n.vh-gutter.vh-nonu .vh-n,\n.vh-gutter.vh-nonu .vh-ln::after { display: none; }\n\n.vh-ln[data-mark]::before {\n  content: attr(data-mark);\n  position: absolute;\n  left: 2px;\n  color: var(--vh-mark);\n  font-weight: 700;\n}\n\n.vh-ln.vh-ln-c {\n  background: linear-gradient(var(--vh-comment-mark), var(--vh-comment-mark)) no-repeat right 4px top 0 / 3px 100%;\n}\n\n/* A fold heading's number toggles its fold on click or tap. */\n.vh-ln.vh-ln-fold { pointer-events: auto; cursor: pointer; }\n\n/* ---- pre: one inline-block per source line ------------------------------\n   An inline-block's box is the whole line box (an inline span's is only the\n   glyphs' height), so the gutter row and motions.js's cursorline overlay get a\n   full row; the zero-width ::before gives a blank source line that height too.\n   The cursorline itself is motions.js's overlay, not a style here. */\n.vh-pl { display: inline-block; }\n.vh-pl::before { content: \"\\200b\"; }\n\n/* ---- folds -------------------------------------------------------------- */\n@media screen {\n  .vh-folded { display: none !important; }\n\n  [data-vh-fold]::after {\n    content: attr(data-vh-fold);\n    display: inline-block;\n    margin-left: 0.6em;\n    padding: 0.15em 0.6em;\n    border-radius: var(--vh-radius);\n    background: var(--vh-fold-bg);\n    color: var(--vh-fold);\n    font: 500 0.78rem/1.35 var(--vh-font-mono, ui-monospace, monospace);\n    letter-spacing: 0;\n    text-transform: none;\n    vertical-align: middle;\n    white-space: nowrap;\n    cursor: pointer;\n  }\n}\n/* ---- runtime/motions.css ---- */\n/* motions.css -- the cursorline overlay and the message area (:marks, <leader>md).\n   Tokens only. Both live in VH.ui.layer; see motions.js for why the cursorline\n   is an overlay and not a background on the line element. */\n\n.vh-cursorline {\n  position: absolute;\n  display: none;\n  box-sizing: content-box;\n  /* Reach a little past the text on both sides, like a band, without moving it. */\n  margin-left: -0.45rem;\n  padding: 0 0.45rem;\n  border-radius: min(var(--vh-radius, 4px), 5px);\n  background: var(--vh-cursorline);\n  pointer-events: none;\n}\n.vh-cursorline.vh-on { display: block; }\n\n/* .vh-cursor only marks the cursor line's element for other modules. The\n   wave-1 lines.css painted it with background: var(--vh-cursorline), which\n   doubles the overlay and tints an li's nested list; emptying the token on that\n   element alone switches such a rule off and does nothing once it is gone. */\n.vh-cursor { --vh-cursorline: transparent; }\n\n.vh-msg {\n  position: fixed;\n  left: 0;\n  bottom: 28px;\n  max-width: min(640px, 100vw);\n  max-height: 50vh;\n  overflow-y: auto;\n  padding: 6px 0;\n  border: 1px solid var(--vh-line);\n  border-left: 0;\n  border-bottom: 0;\n  border-top-right-radius: var(--vh-radius);\n  background: var(--vh-surface);\n  color: var(--vh-ink);\n  box-shadow: var(--vh-shadow);\n  font: 12px/1.6 var(--vh-font-mono, ui-monospace, monospace);\n}\n.vh-msg-title { padding: 0 12px 2px; color: var(--vh-muted); white-space: pre; }\n.vh-msg-row { display: flex; gap: 12px; padding: 0 12px; white-space: nowrap; }\n.vh-msg-pick { cursor: pointer; }\n.vh-msg-pick:hover { background: var(--vh-accent-soft); }\n.vh-msg-key { width: 2ch; text-align: center; color: var(--vh-mark, var(--vh-accent)); font-weight: 700; }\n.vh-msg-line { min-width: 4ch; text-align: right; color: var(--vh-muted); font-variant-numeric: tabular-nums; }\n.vh-msg-text { overflow: hidden; text-overflow: ellipsis; }\n/* ---- runtime/search.css ---- */\n/* search.css -- piece D: search highlights, the command line and its messages,\n   the wildmenu, the fuzzy pickers and the outline. Tokens only.\n\n   Search colours are the owner's nvim `Search` (bright red, white text) in both\n   schemes; the current match is a darker red with a yellow underline so it\n   stands out among the others. ::highlight() can only set colours and text\n   decoration, which is why the \"ring\" is an underline. */\n\n::highlight(vh-search) {\n  background-color: var(--vh-search);\n  color: var(--vh-on-search);\n}\n::highlight(vh-search-cur) {\n  background-color: var(--vh-search-cur);\n  color: var(--vh-on-search);\n  text-decoration: underline;\n  text-decoration-color: var(--vh-search-outline);\n  text-decoration-thickness: 3px;\n  text-underline-offset: 2px;\n}\n\n.vh-cmdline[hidden], .vh-cmdmsg[hidden], .vh-wild[hidden], .vh-ol[hidden], .vh-search-count[hidden] { display: none; }\n\n/* \"[3/17]\" after the current match's line (search.js showCount) */\n.vh-search-count {\n  position: absolute;\n  padding: 0 7px;\n  border-radius: 999px;\n  background: var(--vh-sunk);\n  color: var(--vh-muted);\n  font: 11px/18px var(--vh-font-mono);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n  pointer-events: none;\n}\n\n/* The command line and the message strip sit exactly over the status line\n   (chrome.css, 28px, z-index 2) while they show. */\n.vh-cmdline, .vh-cmdmsg {\n  position: fixed;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  height: 28px;\n  padding: 0 10px;\n  background: var(--vh-surface);\n  border-top: 1px solid var(--vh-edge);\n  color: var(--vh-ink);\n  font: 13px/27px var(--vh-font-mono);\n  z-index: 3;\n}\n.vh-cmdline { display: flex; align-items: center; gap: 1px; }\n.vh-cmd-prompt { color: var(--vh-accent-ink); font-weight: 700; }\n.vh-cmd-input {\n  flex: 1;\n  min-width: 0;\n  height: 100%;\n  border: 0;\n  outline: 0;\n  padding: 0;\n  background: transparent;\n  color: var(--vh-ink);\n  caret-color: var(--vh-accent);\n  font: inherit;\n}\n.vh-cmdmsg { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.vh-cmdmsg-error { color: var(--vh-bad); font-weight: 600; }\n.vh-cmdmsg-warn { color: var(--vh-warn); }\n\n/* wildmenu: the completions above the command line, current one filled */\n.vh-wild {\n  position: fixed;\n  left: 18px;\n  bottom: 32px;\n  min-width: 180px;\n  max-width: calc(100vw - 36px);\n  max-height: 40vh;\n  overflow: auto;\n  padding: 4px 0;\n  background: var(--vh-surface);\n  border: 1px solid var(--vh-edge);\n  border-radius: var(--vh-radius);\n  box-shadow: var(--vh-shadow);\n  font: 13px/1.5 var(--vh-font-mono);\n  z-index: 3;\n}\n.vh-wild-item { padding: 1px 14px; white-space: nowrap; color: var(--vh-ink); }\n.vh-wild-item.vh-sel { background: var(--vh-accent); color: var(--vh-on-accent); }\n\n/* ---- pickers: a centred float like fzf-lua's, prompt on top, best match first */\n\n.vh-pk {\n  position: fixed;\n  left: 50%;\n  top: 12vh;\n  transform: translateX(-50%);\n  width: min(780px, calc(100vw - 32px));\n  background: var(--vh-surface);\n  border: 1px solid var(--vh-edge);\n  border-radius: var(--vh-radius);\n  box-shadow: var(--vh-shadow);\n  color: var(--vh-ink);\n  font: 13px/1.4 var(--vh-font-mono);\n  overflow: hidden;\n  z-index: 4;\n}\n.vh-pk-bar {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 7px 12px 0;\n  font-family: var(--vh-font-body);\n  font-size: 12px;\n  color: var(--vh-muted);\n}\n.vh-pk-title { color: var(--vh-accent-ink); font-weight: 700; letter-spacing: 0.02em; }\n.vh-pk-count { font-family: var(--vh-font-mono); font-variant-numeric: tabular-nums; }\n.vh-pk-prompt {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 6px 8px;\n  padding: 0 8px;\n  height: 32px;\n  border: 1px solid var(--vh-line);\n  border-radius: calc(var(--vh-radius) * 0.7);\n  background: var(--vh-bg);\n}\n.vh-pk-caret { color: var(--vh-accent-ink); font-weight: 700; }\n.vh-pk-input {\n  flex: 1;\n  min-width: 0;\n  border: 0;\n  outline: 0;\n  padding: 0;\n  background: transparent;\n  color: var(--vh-ink);\n  caret-color: var(--vh-accent);\n  font: inherit;\n  font-size: 14px;\n}\n.vh-pk-list { position: relative; overflow: hidden; padding-bottom: 4px; }\n.vh-pk-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  height: 26px;\n  padding: 0 12px 0 10px;\n  border-left: 2px solid transparent;\n  white-space: nowrap;\n  cursor: pointer;\n}\n.vh-pk-row:hover { background: var(--vh-sunk); }\n.vh-pk-row.vh-sel { background: var(--vh-accent-soft); border-left-color: var(--vh-accent); }\n.vh-pk-ln, .vh-pk-lv {\n  flex: none;\n  width: 4ch;\n  text-align: right;\n  color: var(--vh-faint);\n  font-variant-numeric: tabular-nums;\n}\n.vh-pk-lv { width: 3ch; text-align: left; font-size: 11px; }\n.vh-pk-tx { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; color: var(--vh-ink); }\n.vh-pk-hit { background: none; color: var(--vh-accent-ink); font-weight: 700; text-decoration: underline; text-underline-offset: 2px; }\n.vh-pk-empty { padding: 6px 14px; color: var(--vh-faint); }\n\n/* ---- outline: a narrow right-side panel above the status line.\n   --vh-ol-w is shared: chrome.css moves the sun/moon toggle to the outline's\n   left edge while html.vh-outline-open, so it never covers the close button. */\n\n:root { --vh-ol-w: clamp(190px, 18vw, 280px); }\n\n.vh-ol {\n  position: fixed;\n  top: 0;\n  right: 0;\n  bottom: 28px;\n  width: var(--vh-ol-w);\n  display: flex;\n  flex-direction: column;\n  background: var(--vh-surface);\n  border-left: 1px solid var(--vh-line);\n  color: var(--vh-ink);\n  font: 12.5px/1.35 var(--vh-font-body);\n  z-index: 1;\n}\n.vh-ol-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 8px 6px 6px 12px;\n  border-bottom: 1px solid var(--vh-line);\n  color: var(--vh-muted);\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n.vh-ol.vh-focus .vh-ol-head { color: var(--vh-accent-ink); }\n.vh-ol-close {\n  padding: 0 6px;\n  border: 0;\n  border-radius: calc(var(--vh-radius) * 0.6);\n  background: none;\n  color: var(--vh-muted);\n  font: 16px/1.2 var(--vh-font-body);\n  cursor: pointer;\n}\n.vh-ol-close:hover { background: var(--vh-sunk); color: var(--vh-ink); }\n.vh-ol-list { position: relative; flex: 1; overflow: auto; padding: 4px 0 8px; outline: 0; }\n.vh-ol-item {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  padding: 3px 10px;\n  border-left: 2px solid transparent;\n  color: var(--vh-muted);\n  cursor: pointer;\n}\n.vh-ol-item[data-level=\"1\"], .vh-ol-item[data-level=\"2\"] { color: var(--vh-ink); }\n.vh-ol-item:hover { background: var(--vh-sunk); }\n.vh-ol-text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.vh-ol-ln { flex: none; color: var(--vh-faint); font: 11px var(--vh-font-mono); font-variant-numeric: tabular-nums; }\n.vh-ol-item.vh-cur { border-left-color: var(--vh-accent); background: var(--vh-accent-soft); color: var(--vh-accent-ink); font-weight: 600; }\n.vh-ol-item.vh-sel { box-shadow: inset 0 0 0 1px var(--vh-accent); }\n.vh-ol-empty { padding: 8px 12px; color: var(--vh-faint); }\n\n@media print {\n  html.vh-outline-open { padding-right: 0 !important; }\n}\n/* ---- runtime/select.css ---- */\n/* select.css -- visual modes (piece E). Tokens only.\n   Character visual is the browser's own selection, recoloured with --vh-visual;\n   fields (the page's and ours) keep native colours so they look as they always\n   do. The rule must not depend on the mode: html[data-vh-mode=...] ::selection\n   made every element's style depend on that attribute, and each mode change\n   (:, Esc, i) restyled the whole document, ~40 ms on 2,000 lines. Visual line\n   paints whole line elements. */\n\n::selection { background-color: var(--vh-visual); }\n:is(input, textarea, select)::selection,\n[contenteditable] ::selection { background-color: Highlight; }\n\n.vh-vline,\n.vh-vline.vh-cursor { background: var(--vh-visual) !important; border-radius: 2px; }\n\n/* The one-click comment button at the end of a mouse selection. */\n.vh-sel-btn {\n  position: absolute;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 3px 6px 3px 8px;\n  border: 1px solid var(--vh-edge);\n  border-radius: var(--vh-radius);\n  background: var(--vh-surface);\n  color: var(--vh-ink);\n  box-shadow: var(--vh-shadow);\n  font: 600 12px/1.3 var(--vh-font-body, system-ui, sans-serif);\n  white-space: nowrap;\n  cursor: pointer;\n}\n.vh-sel-btn:hover { background: var(--vh-accent-soft); }\n.vh-sel-btn:focus-visible { outline: 2px solid var(--vh-accent); outline-offset: 1px; }\n.vh-sel-btn-icon { color: var(--vh-accent-ink); font-weight: 800; }\n.vh-sel-btn kbd {\n  padding: 0 4px;\n  border: 1px solid var(--vh-line);\n  border-radius: 3px;\n  background: var(--vh-sunk);\n  color: var(--vh-muted);\n  font: 10px/1.5 var(--vh-font-mono, ui-monospace, monospace);\n}\n\n@media print { .vh-vline { background: none !important; } }\n/* ---- runtime/comments.css ---- */\n/* comments.css -- comment highlights, the editor and the K popover (piece E).\n   Highlights go through the CSS Custom Highlight API (see comments.js), so the\n   document's DOM is never wrapped or split. Tokens only. */\n\n::highlight(vh-comment) { background-color: var(--vh-comment); }\n::highlight(vh-comment-cur) {\n  background-color: var(--vh-comment);\n  text-decoration: underline 2px var(--vh-comment-mark);\n  text-underline-offset: 3px;\n}\n::highlight(vh-comment-draft) { background-color: var(--vh-visual); }\n\n/* editor: absolute in VH.ui.layer, under the last commented line */\n.vh-editor {\n  position: absolute;\n  padding: 10px 12px 9px;\n  background: var(--vh-surface);\n  border: 1px solid var(--vh-edge);\n  border-left: 3px solid var(--vh-comment-mark);\n  border-radius: var(--vh-radius);\n  box-shadow: var(--vh-shadow);\n}\n.vh-editor-head {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  min-width: 0;\n  font: 11px/1.4 var(--vh-font-mono, ui-monospace, monospace);\n  color: var(--vh-muted);\n}\n.vh-editor-ref { color: var(--vh-accent-ink); font-weight: 700; white-space: nowrap; }\n.vh-editor-path { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.vh-editor-state {\n  margin-left: auto;\n  padding: 0 5px;\n  border-radius: 3px;\n  background: var(--vh-sunk);\n  color: var(--vh-faint);\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  font-size: 10px;\n}\n.vh-editor-quote {\n  margin: 6px 0 8px;\n  padding-left: 9px;\n  border-left: 2px solid var(--vh-line);\n  color: var(--vh-muted);\n  font-size: 12.5px;\n  line-height: 1.45;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  max-height: 4.4em;\n  overflow: hidden;\n}\n.vh-editor-note {\n  display: block;\n  width: 100%;\n  min-height: 2.6em;\n  resize: none;\n  padding: 6px 8px;\n  border: 1px solid var(--vh-line);\n  border-radius: calc(var(--vh-radius) * 0.6);\n  background: var(--vh-bg);\n  color: var(--vh-ink);\n  font: 14px/1.45 var(--vh-font-body, system-ui, sans-serif);\n}\n.vh-editor-note::placeholder { color: var(--vh-faint); }\n.vh-editor-note:focus { outline: 2px solid var(--vh-accent); outline-offset: -1px; }\n.vh-editor-hint { margin-top: 6px; font-size: 11px; color: var(--vh-faint); white-space: pre-wrap; }\n\n.vh-editor kbd, .vh-pop kbd {\n  padding: 0 4px;\n  border: 1px solid var(--vh-line);\n  border-radius: 3px;\n  background: var(--vh-sunk);\n  color: var(--vh-muted);\n  font: 10px/1.5 var(--vh-font-mono, ui-monospace, monospace);\n}\n\n/* K: the note(s) on the cursor line. VH.ui.layer is zero-width, so shrink-to-fit\n   would collapse the box to one word: size it to its content instead. */\n.vh-pop {\n  position: absolute;\n  width: max-content;\n  min-width: 220px;\n  max-width: min(520px, calc(100vw - 32px));\n  padding: 8px 10px;\n  background: var(--vh-surface);\n  border: 1px solid var(--vh-edge);\n  border-left: 3px solid var(--vh-comment-mark);\n  border-radius: var(--vh-radius);\n  box-shadow: var(--vh-shadow);\n}\n.vh-pop-item + .vh-pop-item { margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--vh-line); }\n.vh-pop-ref { font: 700 11px/1.4 var(--vh-font-mono, ui-monospace, monospace); color: var(--vh-accent-ink); }\n.vh-pop-note { margin-top: 2px; color: var(--vh-ink); font-size: 14px; white-space: pre-wrap; overflow-wrap: anywhere; }\n.vh-pop-hint { margin-top: 8px; font-size: 11px; color: var(--vh-faint); white-space: pre-wrap; }\n/* ---- runtime/panel.css ---- */\n/* panel.css -- the comments sidebar (piece F). Tokens only.\n   A fixed right column that stops above the 28px status line, so the status\n   line (and piece D's command line over it) stays visible, like a nvim sidebar\n   above a global statusline. Elements are divs and spans, never the tags\n   doc.css styles (p excepted, reset below). */\n\n.vh-panel {\n  position: fixed;\n  top: 0;\n  right: 0;\n  bottom: 28px;\n  width: min(400px, 100vw);\n  display: flex;\n  flex-direction: column;\n  background: var(--vh-surface);\n  color: var(--vh-ink);\n  border-left: 1px solid var(--vh-edge);\n  font: 13px/1.45 var(--vh-font-body, system-ui, sans-serif);\n  z-index: 5;\n  user-select: none;\n  -webkit-user-select: none;\n}\n.vh-panel[hidden], .vh-panel [hidden] { display: none !important; }\n\n.vh-panel-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 12px 10px 10px 16px;\n  border-bottom: 1px solid var(--vh-line);\n}\n.vh-panel-title { font-weight: 700; font-size: 14px; }\n.vh-panel-n {\n  padding: 0 7px;\n  border-radius: 999px;\n  background: var(--vh-sunk);\n  color: var(--vh-muted);\n  font: 600 11px/18px var(--vh-font-mono, ui-monospace, monospace);\n}\n.vh-panel-sel { color: var(--vh-accent-ink); font-size: 12px; font-weight: 600; }\n.vh-panel-close { margin-left: auto; }\n\n/* ---- buttons ---- */\n\n.vh-pbtn {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  height: 26px;\n  padding: 0 9px;\n  border: 1px solid var(--vh-line);\n  border-radius: calc(var(--vh-radius) * 0.6);\n  background: var(--vh-bg);\n  color: var(--vh-ink);\n  font: 500 12px/1 var(--vh-font-body, system-ui, sans-serif);\n  white-space: nowrap;\n  cursor: pointer;\n}\n.vh-pbtn:hover:not(:disabled) { border-color: var(--vh-edge); background: var(--vh-sunk); }\n.vh-pbtn:disabled { opacity: 0.45; cursor: default; }\n.vh-pbtn.vh-danger { color: var(--vh-bad); }\n.vh-pbtn.vh-danger:hover:not(:disabled) { background: var(--vh-bad-soft); border-color: var(--vh-bad); }\n.vh-pbtn .vh-i, .vh-pbtn svg { display: block; flex: none; }\n.vh-panel-close, .vh-pi-acts .vh-pbtn { width: 26px; padding: 0; justify-content: center; }\n.vh-panel-close { border-color: transparent; background: transparent; color: var(--vh-muted); }\n\n.vh-panel-tools {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  padding: 10px 12px;\n  border-bottom: 1px solid var(--vh-line);\n}\n.vh-act-undo { margin-left: auto; }\n\n/* ---- rows ---- */\n\n.vh-panel-list {\n  position: relative;  /* rows' offsetTop is measured from here */\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  outline: none;\n}\n\n.vh-pi {\n  display: grid;\n  grid-template-columns: 18px minmax(0, 1fr) auto;\n  gap: 10px;\n  padding: 10px 10px 10px 13px;\n  border-left: 3px solid transparent;\n  border-bottom: 1px solid var(--vh-line);\n  cursor: pointer;\n}\n.vh-pi:hover { background: var(--vh-cursorline); }\n.vh-pi.vh-on { background: var(--vh-accent-soft); }\n.vh-pi.vh-cur { border-left-color: var(--vh-accent); background: var(--vh-sunk); }\n.vh-pi.vh-cur.vh-on { background: var(--vh-accent-soft); }\n\n.vh-pi-check {\n  width: 16px;\n  height: 16px;\n  margin-top: 1px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: 1.5px solid var(--vh-faint);\n  border-radius: 4px;\n  background: var(--vh-bg);\n  color: transparent;\n}\n.vh-pi-check svg { width: 12px; height: 12px; stroke-width: 3; }\n.vh-pi:hover .vh-pi-check { border-color: var(--vh-muted); }\n.vh-pi.vh-on .vh-pi-check { background: var(--vh-accent); border-color: var(--vh-accent); color: var(--vh-on-accent); }\n\n.vh-pi-meta { display: flex; align-items: baseline; gap: 8px; min-width: 0; }\n.vh-pi-ref {\n  flex: none;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--vh-accent-ink);\n  font: 600 11.5px/1.4 var(--vh-font-mono, ui-monospace, monospace);\n  cursor: pointer;\n}\n.vh-pi-ref:hover { text-decoration: underline; }\n.vh-pi-path {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  color: var(--vh-faint);\n  font-size: 11.5px;\n}\n.vh-pi-quote {\n  margin-top: 4px;\n  padding-left: 8px;\n  border-left: 2px solid var(--vh-comment-mark);\n  color: var(--vh-muted);\n  font-size: 12px;\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: 2;\n  overflow: hidden;\n}\n.vh-pi-note {\n  margin-top: 5px;\n  color: var(--vh-ink);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n.vh-detached .vh-pi-ref { color: var(--vh-warn); }\n.vh-detached .vh-pi-quote { text-decoration: line-through; text-decoration-color: var(--vh-faint); }\n\n.vh-pi-acts { display: flex; flex-direction: column; gap: 4px; opacity: 0; }\n.vh-pi:hover .vh-pi-acts, .vh-pi.vh-cur .vh-pi-acts { opacity: 1; }\n.vh-pi-acts .vh-pbtn { height: 24px; width: 24px; background: transparent; border-color: transparent; color: var(--vh-muted); }\n.vh-pi-acts .vh-pbtn:hover { border-color: var(--vh-line); background: var(--vh-bg); color: var(--vh-ink); }\n.vh-pi-acts .vh-pbtn.vh-danger:hover { color: var(--vh-bad); background: var(--vh-bad-soft); }\n@media (hover: none) { .vh-pi-acts { opacity: 1; } }\n\n/* ---- empty state and key hints ---- */\n\n.vh-panel-empty { flex: 1; padding: 28px 20px; color: var(--vh-muted); line-height: 1.7; }\n.vh-panel-empty p { margin: 0 0 10px; }\n.vh-panel-empty .vh-panel-empty-head { color: var(--vh-ink); font-weight: 600; font-size: 14px; }\n.vh-panel-empty-q { margin-top: 18px !important; color: var(--vh-faint); }\n\n.vh-panel-keys {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px 10px;\n  padding: 8px 12px 9px;\n  border-top: 1px solid var(--vh-line);\n  background: var(--vh-sunk);\n  color: var(--vh-faint);\n  font-size: 11px;\n}\n.vh-panel-hint { white-space: nowrap; }\n\n/* The comment being previewed, in the document. */\n.vh-peek {\n  outline: 2px solid var(--vh-comment-mark);\n  outline-offset: 3px;\n  border-radius: 2px;\n}\n\n@media print { .vh-peek { outline: none; } }\n/* ---- runtime/chrome.css ---- */\n/* chrome.css -- status line, theme toggle, which-key, help overlay, first-load\n   hint (piece F). Tokens only; the vh-* locals below are derived from them.\n\n   Stacking inside #vh-ui (one stacking context above the page):\n     2 status line   (piece D's command line sits above it, over the same area)\n     3 theme toggle  4 hint   5 comments sidebar   6 help   7 which-key\n     8 core's toast and 9 copy dialog, raised so the sidebar never hides them. */\n\n#vh-ui > .vh-toast { z-index: 8; }\n#vh-ui > .vh-clipdlg { z-index: 9; }\n\n/* --theme none has no doc.css: leave the last line clear of the status line. */\n\n\n/* ---- shared: key chips (also used by panel.js) and icons ---- */\n\n.vh-kbd {\n  display: inline-block;\n  min-width: 1.7em;\n  margin: 0 1px;\n  padding: 0 5px;\n  border: 1px solid var(--vh-line);\n  border-bottom-width: 2px;\n  border-radius: 4px;\n  background: var(--vh-bg);\n  color: var(--vh-ink);\n  font: 600 11px/17px var(--vh-font-mono, ui-monospace, monospace);\n  text-align: center;\n  white-space: nowrap;\n}\n.vh-i { display: inline-flex; flex: none; }\n.vh-i svg { display: block; }\n\n[data-vh-ui] button { -webkit-tap-highlight-color: transparent; }\n[data-vh-ui] button:focus-visible { outline: 2px solid var(--vh-accent); outline-offset: 1px; }\n\n/* ---- status line (lualine) ----\n   a: mode   b: comments   c: title > section   x: memory, search, copy\n   y: progress   z: position. a and z take the mode's colour; the powerline\n   arrows are clipped triangles that carry their section's background. */\n\n.vh-status {\n  --vhst-a: var(--vh-accent);\n  --vhst-a-ink: var(--vh-on-accent);\n  position: fixed;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  height: 28px;\n  display: flex;\n  align-items: stretch;\n  background: var(--vh-sunk);\n  color: var(--vh-muted);\n  font: 12px/28px var(--vh-font-mono, ui-monospace, monospace);\n  white-space: nowrap;\n  z-index: 2;\n  user-select: none;\n  -webkit-user-select: none;\n}\n.vh-status[data-mode=\"insert\"] { --vhst-a: var(--vh-ok); --vhst-a-ink: var(--vh-bg); }\n.vh-status[data-mode=\"visual\"],\n.vh-status[data-mode=\"vline\"] { --vhst-a: var(--vh-warn); --vhst-a-ink: var(--vh-bg); }\n.vh-status[data-mode=\"command\"] { --vhst-a: var(--vh-ink); --vhst-a-ink: var(--vh-bg); }\n\n.vh-st-a, .vh-st-b, .vh-st-y, .vh-st-z { position: relative; display: flex; align-items: center; flex: none; }\n.vh-st-a, .vh-st-z { background: var(--vhst-a); color: var(--vhst-a-ink); font-weight: 700; }\n.vh-st-b, .vh-st-y { background: var(--vh-line); color: var(--vh-ink); }\n\n.vh-st-a { padding: 0 10px 0 11px; letter-spacing: 0.05em; }\n.vh-st-b { padding: 0 6px 0 16px; }\n.vh-st-y { padding: 0 14px 0 8px; }\n.vh-st-z { padding: 0 11px 0 8px; }\n\n.vh-st-a::after, .vh-st-b::after, .vh-st-y::before, .vh-st-z::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  width: 9px;\n  height: 100%;\n  background: inherit;\n  z-index: 1;\n}\n.vh-st-a::after, .vh-st-b::after { right: -9px; clip-path: polygon(0 0, 100% 50%, 0 100%); }\n.vh-st-y::before, .vh-st-z::before { left: -9px; clip-path: polygon(100% 0, 0 50%, 100% 100%); }\n\n.vh-st-count {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  height: 100%;\n  padding: 0 4px;\n  border: 0;\n  background: none;\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n}\n.vh-st-count:hover .vh-st-label { text-decoration: underline; text-underline-offset: 3px; }\n.vh-st-count.vh-zero { color: var(--vh-muted); }\n\n.vh-st-c {\n  flex: 1;\n  min-width: 0;\n  padding: 0 10px 0 19px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.vh-st-title { color: var(--vh-ink); }\n.vh-st-crumb { color: var(--vh-faint); }\n\n.vh-st-x { display: flex; align-items: center; flex: none; gap: 12px; padding: 0 19px 0 8px; }\n.vh-st-mem { display: inline-flex; align-items: center; gap: 5px; color: var(--vh-bad); font-weight: 700; cursor: help; }\n.vh-st-search { color: var(--vh-ink); font-weight: 600; }\n.vh-st-mem[hidden], .vh-st-search[hidden] { display: none; }\n\n.vh-st-copy {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  height: 20px;\n  padding: 0 9px;\n  border: 1px solid var(--vh-accent);\n  border-radius: calc(var(--vh-radius) * 0.6);\n  background: var(--vh-accent-soft);\n  color: var(--vh-accent-ink);\n  font: 600 11.5px/1 var(--vh-font-body, system-ui, sans-serif);\n  cursor: pointer;\n}\n.vh-st-copy:hover { background: var(--vh-accent); border-color: var(--vh-accent); color: var(--vh-on-accent); }\n.vh-st-copy.vh-zero { border-color: var(--vh-line); background: transparent; color: var(--vh-muted); }\n.vh-st-copy svg { width: 13px; height: 13px; }\n\n@media (max-width: 40rem) {\n  .vh-st-crumb, .vh-st-word, .vh-st-y { display: none; }\n  .vh-st-copy-l { display: none; }\n  .vh-st-copy { padding: 0 7px; }\n  .vh-st-x { gap: 8px; padding-right: 16px; }\n}\n\n/* ---- theme toggle ---- */\n\n.vh-theme {\n  position: fixed;\n  top: 10px;\n  right: 12px;\n  width: 32px;\n  height: 32px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  border: 1px solid var(--vh-line);\n  border-radius: 999px;\n  background: var(--vh-surface);\n  color: var(--vh-ink);\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);\n  cursor: pointer;\n  z-index: 3;\n}\n.vh-theme:hover { border-color: var(--vh-edge); background: var(--vh-sunk); }\n/* The outline (search.css) is a right column whose header ends in its close\n   button; the toggle steps to the column's left edge instead of sitting on it.\n   The comments sidebar and help stack above the toggle and simply cover it. */\nhtml.vh-outline-open .vh-theme { right: calc(var(--vh-ol-w, 280px) + 12px); }\n.vh-theme svg { width: 16px; height: 16px; }\n.vh-theme .vh-i-sun, .vh-st-theme .vh-i-sun { display: none; }\n:root[data-vh-scheme=\"dark\"] .vh-theme .vh-i-sun,\n:root[data-vh-scheme=\"dark\"] .vh-st-theme .vh-i-sun { display: inline-flex; }\n:root[data-vh-scheme=\"dark\"] .vh-theme .vh-i-moon,\n:root[data-vh-scheme=\"dark\"] .vh-st-theme .vh-i-moon { display: none; }\n\n/* At doc.css's phone breakpoint the text runs to 1rem from the edge, where a\n   fixed corner button would sit on it; the status line carries the toggle. */\n.vh-st-theme {\n  display: none;\n  align-items: center;\n  justify-content: center;\n  width: 22px;\n  height: 22px;\n  padding: 0;\n  border: 0;\n  background: none;\n  color: var(--vh-ink);\n  cursor: pointer;\n}\n@media (max-width: 40rem) {\n  .vh-theme { display: none; }\n  .vh-st-theme { display: inline-flex; }\n}\n\n/* ---- which-key (LazyVim's helix preset: bottom right, one column) ---- */\n\n.vh-wk {\n  position: fixed;\n  right: 12px;\n  bottom: 38px;\n  min-width: 220px;\n  max-width: min(520px, calc(100vw - 24px));\n  max-height: min(60vh, calc(100vh - 60px));\n  overflow: hidden;\n  padding: 8px 4px 8px 0;\n  border: 1px solid var(--vh-edge);\n  border-radius: var(--vh-radius);\n  background: var(--vh-surface);\n  color: var(--vh-ink);\n  box-shadow: var(--vh-shadow);\n  font: 12.5px/1.6 var(--vh-font-mono, ui-monospace, monospace);\n  z-index: 7;\n}\n.vh-wk[hidden] { display: none; }\n.vh-wk-title {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  margin: 0 0 6px 12px;\n  color: var(--vh-muted);\n}\n.vh-wk-count { color: var(--vh-accent-ink); font-weight: 700; margin-right: 2px; }\n.vh-wk-list { display: grid; grid-auto-flow: row; }\n.vh-wk-list.vh-wk-wide { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 8px; }\n.vh-wk-row { display: flex; align-items: baseline; gap: 8px; padding: 0 12px; white-space: nowrap; }\n.vh-wk-key { min-width: 1.4em; text-align: right; color: var(--vh-accent-ink); font-weight: 700; }\n.vh-wk-sep { color: var(--vh-faint); }\n.vh-wk-desc { overflow: hidden; text-overflow: ellipsis; }\n.vh-wk-group .vh-wk-desc { color: var(--vh-accent-ink); }\n\n/* ---- help overlay ---- */\n\n.vh-help {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 28px;\n  display: flex;\n  align-items: flex-start;\n  justify-content: center;\n  padding: 5vh 16px 16px;\n  background: rgba(0, 0, 0, 0.18);\n  z-index: 6;\n}\n:root[data-vh-scheme=\"dark\"] .vh-help { background: rgba(0, 0, 0, 0.45); }\n.vh-help-box {\n  display: flex;\n  flex-direction: column;\n  width: min(1040px, 100%);\n  max-height: 100%;\n  border: 1px solid var(--vh-edge);\n  border-radius: var(--vh-radius);\n  background: var(--vh-surface);\n  color: var(--vh-ink);\n  box-shadow: var(--vh-shadow);\n}\n.vh-help-head {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 12px 12px 12px 20px;\n  border-bottom: 1px solid var(--vh-line);\n}\n.vh-help-title { font-weight: 700; font-size: 15px; }\n.vh-help-sub { color: var(--vh-muted); font-size: 12px; }\n.vh-help-close {\n  margin-left: auto;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 28px;\n  height: 28px;\n  padding: 0;\n  border: 1px solid transparent;\n  border-radius: calc(var(--vh-radius) * 0.6);\n  background: none;\n  color: var(--vh-muted);\n  cursor: pointer;\n}\n.vh-help-close:hover { border-color: var(--vh-line); background: var(--vh-sunk); color: var(--vh-ink); }\n.vh-help-close svg { width: 16px; height: 16px; }\n.vh-help-body {\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  padding: 14px 20px 20px;\n  columns: 300px 3;\n  column-gap: 32px;\n  outline: none;\n}\n.vh-help-sec { break-inside: avoid; margin: 0 0 18px; }\n.vh-help-h {\n  margin: 0 0 6px;\n  padding-bottom: 4px;\n  border-bottom: 1px solid var(--vh-line);\n  color: var(--vh-accent-ink);\n  font: 700 11px/1.4 var(--vh-font-mono, ui-monospace, monospace);\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n.vh-help-row { display: flex; align-items: baseline; gap: 10px; padding: 2px 0; font-size: 12.5px; }\n.vh-help-k { flex: none; width: 8.2em; display: flex; flex-wrap: wrap; gap: 3px; }\n.vh-help-d { flex: 1; min-width: 0; color: var(--vh-ink); }\n.vh-keys { display: inline-flex; gap: 2px; }\n.vh-keys .vh-kbd { margin: 0; }\n.vh-help-in {\n  margin: 8px 0 3px;\n  color: var(--vh-faint);\n  font-size: 11.5px;\n  font-style: italic;\n}\n.vh-cmd { color: var(--vh-accent-ink); font: 600 12px/18px var(--vh-font-mono, ui-monospace, monospace); }\n\n@media (max-width: 40rem) {\n  .vh-help { padding: 8px; }\n  .vh-help-sub { display: none; }\n  .vh-help-body { padding: 12px 14px 16px; }\n}\n\n/* ---- first-load hint ---- */\n\n.vh-hint {\n  position: fixed;\n  left: 50%;\n  bottom: 40px;\n  max-width: calc(100vw - 32px);\n  padding: 7px 14px;\n  border: 1px solid var(--vh-edge);\n  border-radius: 999px;\n  background: var(--vh-surface);\n  color: var(--vh-muted);\n  box-shadow: var(--vh-shadow);\n  font: 12.5px/18px var(--vh-font-body, system-ui, sans-serif);\n  white-space: nowrap;\n  opacity: 0;\n  transform: translate(-50%, 6px);\n  transition: opacity 0.2s, transform 0.2s;\n  pointer-events: none;\n  z-index: 4;\n}\n.vh-hint.vh-show { opacity: 1; transform: translate(-50%, 0); }\n.vh-hint b { color: var(--vh-accent-ink); font: 700 11.5px var(--vh-font-mono, ui-monospace, monospace); letter-spacing: 0.05em; }/* Keep the discoverable hosting controls inside the runtime's own UI layer. */\n#vh-ui .docs-vim-controls { position: fixed; right: 8px; bottom: 36px; display: flex; gap: 4px; z-index: 10; }\n#vh-ui .docs-vim-controls button { font: 12px/1.4 system-ui, sans-serif; color: var(--vh-ink); background: var(--vh-bg); border: 1px solid var(--vh-edge); border-radius: 4px; padding: 3px 6px; cursor: pointer; }\n[data-docs-vim-off] #vh-ui > :not(.docs-vim-controls) { display: none !important; }\n@media print { #vh-ui .docs-vim-controls { display: none; } }\n";
